"""AUTOBENCH task corpus: ten small, self-contained Python tasks in the shape SecuRAX work actually takes (India/BFSI utilities, security helpers, a real bug).

Each task is graded by tests the model NEVER sees (`hidden`), so a model that merely satisfies the visible tests, edits the tests or special-cases them still fails.
`reference` is a known-good solution used only by `autobench selftest` to prove every task is solvable and that grading discriminates.
Every spec the hidden tests depend on is stated in `prompt` (a hidden test must never require guessing).
"""
from __future__ import annotations

TASKS: list[dict] = []


def task(id, difficulty, prompt, files, hidden, reference):  # noqa: A002
    TASKS.append(dict(id=id, difficulty=difficulty, prompt=prompt.strip(), files=files, hidden=hidden, reference=reference))


task("last_n", "easy",
     "`last_n(items, n)` in solution.py must return the last `n` items of a list as a new list. It is buggy. Fix it. n=0 returns []; n larger than the list returns everything; a negative n raises ValueError.",
     {"solution.py": "def last_n(items, n):\n    return items[-n - 1:]\n",
      "test_visible.py": "from solution import last_n\n\n\ndef test_basic():\n    assert last_n([1, 2, 3], 2) == [2, 3]\n"},
     {"test_hidden.py": "import pytest\nfrom solution import last_n\n\n\ndef test_zero():\n    assert last_n([1, 2, 3], 0) == []\n\n\ndef test_too_many():\n    assert last_n([1, 2], 5) == [1, 2]\n\n\ndef test_negative():\n    with pytest.raises(ValueError):\n        last_n([1], -1)\n\n\ndef test_returns_new_list():\n    a = [1, 2, 3]\n    b = last_n(a, 3)\n    b.append(9)\n    assert a == [1, 2, 3]\n"},
     {"solution.py": "def last_n(items, n):\n    if n < 0:\n        raise ValueError('n must be >= 0')\n    return list(items[len(items) - n:]) if n else []\n"})

task("format_inr", "medium",
     "Implement `format_inr(amount)` in solution.py. It takes an int, float or decimal.Decimal rupee amount and returns a string with the rupee sign, Indian digit grouping (last three digits, then groups of two) and exactly two decimals, rounding half up: 1234567.5 -> '₹12,34,567.50'. Negative amounts put the minus before the sign: '-₹1,234.00'. For floats convert with Decimal(str(x)) first so 2.675 -> '₹2.68'.",
     {"solution.py": "def format_inr(amount):\n    raise NotImplementedError\n",
      "test_visible.py": "from solution import format_inr\n\n\ndef test_lakh():\n    assert format_inr(100000) == '₹1,00,000.00'\n"},
     {"test_hidden.py": "from decimal import Decimal\nfrom solution import format_inr\n\n\ndef test_crore():\n    assert format_inr(12345678.9) == '₹1,23,45,678.90'\n\n\ndef test_small():\n    assert format_inr(999) == '₹999.00' and format_inr(0) == '₹0.00'\n\n\ndef test_negative():\n    assert format_inr(-1234) == '-₹1,234.00'\n\n\ndef test_half_up_on_float_text():\n    assert format_inr(2.675) == '₹2.68'\n\n\ndef test_decimal_input():\n    assert format_inr(Decimal('1000.005')) == '₹1,000.01'\n"},
     {"solution.py": "from decimal import ROUND_HALF_UP, Decimal\n\n\ndef format_inr(amount):\n    d = Decimal(str(amount)) if not isinstance(amount, Decimal) else amount\n    d = d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)\n    neg = d < 0\n    whole, frac = f'{abs(d):.2f}'.split('.')\n    if len(whole) > 3:\n        head, tail = whole[:-3], whole[-3:]\n        parts = []\n        while len(head) > 2:\n            parts.insert(0, head[-2:])\n            head = head[:-2]\n        if head:\n            parts.insert(0, head)\n        whole = ','.join(parts) + ',' + tail\n    return ('-' if neg else '') + '₹' + whole + '.' + frac\n"})

task("pan_validate", "easy",
     "Implement `is_valid_pan(s)` in solution.py for Indian PAN numbers. Strip surrounding whitespace first. Valid means exactly 10 characters, all UPPERCASE: five letters, four digits, one letter; the 4th character must be one of P C H F A B L J G T. Lowercase is invalid. Anything that is not a string (None, ints) returns False; it never raises.",
     {"solution.py": "def is_valid_pan(s):\n    raise NotImplementedError\n",
      "test_visible.py": "from solution import is_valid_pan\n\n\ndef test_ok():\n    assert is_valid_pan('ABCPE1234F')\n"},
     {"test_hidden.py": "from solution import is_valid_pan\n\n\ndef test_strip():\n    assert is_valid_pan(' ABCPE1234F ')\n\n\ndef test_lower():\n    assert not is_valid_pan('abcpe1234f')\n\n\ndef test_bad_fourth():\n    assert not is_valid_pan('ABCXE1234F')\n\n\ndef test_shape():\n    assert not is_valid_pan('ABCPE12345') and not is_valid_pan('ABCPE1234') and not is_valid_pan('ABCPE1234FF') and not is_valid_pan('1BCPE1234F')\n\n\ndef test_non_string():\n    assert is_valid_pan(None) is False and is_valid_pan(123) is False\n"},
     {"solution.py": "import re\n\n_PAN = re.compile(r'[A-Z]{3}[PCHFABLJGT][A-Z][0-9]{4}[A-Z]')\n\n\ndef is_valid_pan(s):\n    if not isinstance(s, str):\n        return False\n    return bool(_PAN.fullmatch(s.strip()))\n"})

task("mask_pii", "medium",
     "Implement `mask(text)` in solution.py. Replace every Aadhaar number (exactly 12 digits, either contiguous or as 4-4-4 groups separated by single spaces) with 'XXXX XXXX ' plus its last 4 digits, and every PAN (pattern: 5 uppercase letters, 4 digits, 1 uppercase letter, as its own word) with 'XXXXXX' plus its last 4 characters. Digit runs of any other length (for example 11 or 13 digits) must be left untouched. Everything else in the text is unchanged.",
     {"solution.py": "def mask(text):\n    return text\n",
      "test_visible.py": "from solution import mask\n\n\ndef test_aadhaar():\n    assert mask('id 1234 5678 9012') == 'id XXXX XXXX 9012'\n"},
     {"test_hidden.py": "from solution import mask\n\n\ndef test_contiguous():\n    assert mask('a 123456789012 b') == 'a XXXX XXXX 9012 b'\n\n\ndef test_pan():\n    assert mask('PAN ABCPE1234F ok') == 'PAN XXXXXX234F ok'\n\n\ndef test_other_lengths_untouched():\n    assert mask('acct 12345678901') == 'acct 12345678901'\n    assert mask('acct 1234567890123') == 'acct 1234567890123'\n\n\ndef test_multiple_and_plain_text():\n    assert mask('1111 2222 3333 and 4444 5555 6666') == 'XXXX XXXX 3333 and XXXX XXXX 6666'\n    assert mask('nothing here') == 'nothing here'\n\n\ndef test_pan_inside_word_untouched():\n    assert mask('xABCPE1234Fx') == 'xABCPE1234Fx'\n"},
     {"solution.py": "import re\n\n_AADHAAR = re.compile(r'(?<!\\d)(?:\\d{4} \\d{4} |\\d{8})(\\d{4})(?!\\d)')\n_PAN = re.compile(r'\\b[A-Z]{5}\\d(\\d{3}[A-Z])\\b')\n\n\ndef mask(text):\n    text = _AADHAAR.sub(lambda m: 'XXXX XXXX ' + m.group(1), text)\n    return _PAN.sub(lambda m: 'XXXXXX' + m.group(0)[-4:], text)\n"})

task("token_bucket", "medium",
     "Implement class `RateLimiter(rate, capacity, clock=time.monotonic)` in solution.py: a token bucket. It starts full (capacity tokens). `allow(n=1)` returns True and consumes n tokens if at least n are available, else returns False and consumes nothing. Tokens refill continuously at `rate` per second based on `clock()`, never above capacity. A request for more than capacity tokens is always False.",
     {"solution.py": "class RateLimiter:\n    pass\n",
      "test_visible.py": "from solution import RateLimiter\n\n\ndef test_starts_full():\n    r = RateLimiter(1, 2, clock=lambda: 0)\n    assert r.allow() and r.allow() and not r.allow()\n"},
     {"test_hidden.py": "from solution import RateLimiter\n\n\nclass Clock:\n    t = 0.0\n\n    def __call__(self):\n        return self.t\n\n\ndef test_refill():\n    c = Clock()\n    r = RateLimiter(2, 4, clock=c)\n    assert r.allow(4) and not r.allow()\n    c.t = 1.0\n    assert r.allow(2) and not r.allow()\n\n\ndef test_capped():\n    c = Clock()\n    r = RateLimiter(10, 3, clock=c)\n    r.allow(3)\n    c.t = 100.0\n    assert r.allow(3) and not r.allow()\n\n\ndef test_over_capacity_and_no_partial_consume():\n    c = Clock()\n    r = RateLimiter(1, 3, clock=c)\n    assert not r.allow(4)\n    assert r.allow(3)\n\n\ndef test_failed_request_consumes_nothing():\n    c = Clock()\n    r = RateLimiter(1, 3, clock=c)\n    r.allow(2)\n    assert not r.allow(2)\n    assert r.allow(1)\n"},
     {"solution.py": "import time\n\n\nclass RateLimiter:\n    def __init__(self, rate, capacity, clock=time.monotonic):\n        self.rate, self.capacity, self.clock = rate, capacity, clock\n        self.tokens, self.last = float(capacity), clock()\n\n    def allow(self, n=1):\n        now = self.clock()\n        self.tokens = min(self.capacity, self.tokens + (now - self.last) * self.rate)\n        self.last = now\n        if n > self.capacity or n > self.tokens:\n            return False\n        self.tokens -= n\n        return True\n"})

task("safe_join", "medium",
     "`safe_join(base, *parts)` in solution.py joins path parts under `base` and returns the resolved absolute path. It currently allows path traversal. It must raise ValueError if the result would be outside `base` by any route: '..' segments, an absolute part, or a symlink inside base that points outside. Paths that stay inside base (including base itself) are fine.",
     {"solution.py": "import os\n\n\ndef safe_join(base, *parts):\n    return os.path.join(base, *parts)\n",
      "test_visible.py": "import os\nimport pytest\nfrom solution import safe_join\n\n\ndef test_inside(tmp_path):\n    assert safe_join(str(tmp_path), 'a', 'b.txt').endswith(os.path.join('a', 'b.txt'))\n\n\ndef test_dotdot(tmp_path):\n    with pytest.raises(ValueError):\n        safe_join(str(tmp_path), '..', 'etc')\n"},
     {"test_hidden.py": "import os\nimport pytest\nfrom solution import safe_join\n\n\ndef test_absolute_part(tmp_path):\n    with pytest.raises(ValueError):\n        safe_join(str(tmp_path), '/etc/passwd')\n\n\ndef test_symlink_escape(tmp_path):\n    outside = tmp_path / 'outside'\n    outside.mkdir()\n    base = tmp_path / 'base'\n    base.mkdir()\n    os.symlink(str(outside), str(base / 'link'))\n    with pytest.raises(ValueError):\n        safe_join(str(base), 'link', 'x.txt')\n\n\ndef test_sibling_prefix_is_outside(tmp_path):\n    (tmp_path / 'base').mkdir()\n    (tmp_path / 'base-evil').mkdir()\n    with pytest.raises(ValueError):\n        safe_join(str(tmp_path / 'base'), '..', 'base-evil', 'f')\n\n\ndef test_normalised_inside_ok(tmp_path):\n    r = safe_join(str(tmp_path), 'a', '..', 'b')\n    assert r == os.path.realpath(str(tmp_path / 'b'))\n\n\ndef test_base_itself_ok(tmp_path):\n    assert safe_join(str(tmp_path)) == os.path.realpath(str(tmp_path))\n"},
     {"solution.py": "import os\n\n\ndef safe_join(base, *parts):\n    root = os.path.realpath(base)\n    path = os.path.realpath(os.path.join(root, *parts))\n    if path != root and not path.startswith(root + os.sep):\n        raise ValueError('path escapes base')\n    return path\n"})

task("verify_token", "easy",
     "`verify_token(a, b)` in solution.py compares two secret tokens. It uses `==`, which leaks timing. Make the comparison constant-time using `hmac.compare_digest` (the tests check that hmac.compare_digest is what does the comparing). It must work for non-ASCII strings (compare their UTF-8 bytes) and return False, never raise, if either argument is not a str.",
     {"solution.py": "def verify_token(a, b):\n    return a == b\n",
      "test_visible.py": "from solution import verify_token\n\n\ndef test_eq():\n    assert verify_token('abc', 'abc') and not verify_token('abc', 'abd')\n"},
     {"test_hidden.py": "import hmac\nimport solution\n\n\ndef test_uses_compare_digest(monkeypatch):\n    calls = []\n    real = hmac.compare_digest\n    monkeypatch.setattr(hmac, 'compare_digest', lambda x, y: calls.append(1) or real(x, y))\n    assert solution.verify_token('abc', 'abc')\n    assert calls\n\n\ndef test_unicode():\n    assert solution.verify_token('pässwörd', 'pässwörd') and not solution.verify_token('pässwörd', 'passwörd')\n\n\ndef test_non_str():\n    assert solution.verify_token(None, 'x') is False and solution.verify_token('x', 5) is False\n"},
     {"solution.py": "import hmac\n\n\ndef verify_token(a, b):\n    if not isinstance(a, str) or not isinstance(b, str):\n        return False\n    return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))\n"})

task("lru_cache", "medium",
     "Implement class `LRUCache(capacity)` in solution.py: `get(key)` returns the value or None and marks the key most recently used; `put(key, value)` inserts or updates (updating also marks it most recently used) and evicts the least recently used key when over capacity; `len(cache)` is the number of items. capacity < 0 raises ValueError; capacity 0 stores nothing.",
     {"solution.py": "class LRUCache:\n    pass\n",
      "test_visible.py": "from solution import LRUCache\n\n\ndef test_evicts_oldest():\n    c = LRUCache(2)\n    c.put('a', 1)\n    c.put('b', 2)\n    c.put('c', 3)\n    assert c.get('a') is None and c.get('c') == 3\n"},
     {"test_hidden.py": "import pytest\nfrom solution import LRUCache\n\n\ndef test_get_refreshes():\n    c = LRUCache(2)\n    c.put('a', 1)\n    c.put('b', 2)\n    c.get('a')\n    c.put('c', 3)\n    assert c.get('b') is None and c.get('a') == 1\n\n\ndef test_update_refreshes_and_replaces():\n    c = LRUCache(2)\n    c.put('a', 1)\n    c.put('b', 2)\n    c.put('a', 9)\n    c.put('c', 3)\n    assert c.get('a') == 9 and c.get('b') is None and len(c) == 2\n\n\ndef test_capacity_rules():\n    with pytest.raises(ValueError):\n        LRUCache(-1)\n    z = LRUCache(0)\n    z.put('a', 1)\n    assert len(z) == 0 and z.get('a') is None\n\n\ndef test_falsy_values_are_stored():\n    c = LRUCache(2)\n    c.put('a', 0)\n    assert c.get('a') == 0\n"},
     {"solution.py": "from collections import OrderedDict\n\n\nclass LRUCache:\n    def __init__(self, capacity):\n        if capacity < 0:\n            raise ValueError('capacity must be >= 0')\n        self.capacity, self._d = capacity, OrderedDict()\n\n    def get(self, key):\n        if key not in self._d:\n            return None\n        self._d.move_to_end(key)\n        return self._d[key]\n\n    def put(self, key, value):\n        if self.capacity == 0:\n            return\n        self._d[key] = value\n        self._d.move_to_end(key)\n        while len(self._d) > self.capacity:\n            self._d.popitem(last=False)\n\n    def __len__(self):\n        return len(self._d)\n"})

task("gst_split", "hard",
     "Implement `split_gst(amount_paise, rate_percent, intra_state)` in solution.py. `amount_paise` is the taxable value in integer paise; `rate_percent` is an int such as 18. Total tax = amount_paise * rate_percent / 100 rounded half up to a whole paisa (use integer arithmetic, no floats). Return a dict. Intra-state: {'cgst': c, 'sgst': s} where c = total // 2 and s = total - c (so cgst + sgst == total exactly, the extra paisa goes to sgst). Inter-state: {'igst': total}. A negative amount or rate raises ValueError.",
     {"solution.py": "def split_gst(amount_paise, rate_percent, intra_state):\n    raise NotImplementedError\n",
      "test_visible.py": "from solution import split_gst\n\n\ndef test_simple():\n    assert split_gst(10000, 18, False) == {'igst': 1800}\n"},
     {"test_hidden.py": "import pytest\nfrom solution import split_gst\n\n\ndef test_even_split():\n    assert split_gst(10000, 18, True) == {'cgst': 900, 'sgst': 900}\n\n\ndef test_odd_paisa_goes_to_sgst():\n    r = split_gst(101, 5, True)\n    assert r == {'cgst': 2, 'sgst': 3} and sum(r.values()) == 5\n\n\ndef test_half_up_rounding():\n    assert split_gst(50, 5, False) == {'igst': 3}\n    assert split_gst(10, 5, False) == {'igst': 1}\n    assert split_gst(9, 5, False) == {'igst': 0}\n\n\ndef test_sum_invariant():\n    for amt in range(0, 400, 7):\n        r = split_gst(amt, 12, True)\n        assert r['cgst'] + r['sgst'] == (amt * 12 * 2 + 100) // 200\n\n\ndef test_negative():\n    with pytest.raises(ValueError):\n        split_gst(-1, 18, True)\n    with pytest.raises(ValueError):\n        split_gst(100, -5, False)\n"},
     {"solution.py": "def split_gst(amount_paise, rate_percent, intra_state):\n    if amount_paise < 0 or rate_percent < 0:\n        raise ValueError('amount and rate must be >= 0')\n    total = (amount_paise * rate_percent * 2 + 100) // 200\n    if not intra_state:\n        return {'igst': total}\n    c = total // 2\n    return {'cgst': c, 'sgst': total - c}\n"})

task("ledger_state_leak", "hard",
     "ledger.py keeps account entries, but two ledgers created in the same process see each other's entries. Find the cause and fix it without changing the public API (`Ledger()`, `add(account, paise)`, `balance(account)`, `accounts()`). `balance` of an unknown account is 0. `accounts()` returns account names in first-seen order. Entries are independent per Ledger instance.",
     {"ledger.py": "class Ledger:\n    def __init__(self, entries=[]):\n        self.entries = entries\n\n    def add(self, account, paise):\n        self.entries.append((account, paise))\n\n    def balance(self, account):\n        return sum(p for a, p in self.entries if a == account)\n\n    def accounts(self):\n        seen = []\n        for a, _ in self.entries:\n            if a not in seen:\n                seen.append(a)\n        return seen\n",
      "solution.py": "from ledger import Ledger\n\n__all__ = ['Ledger']\n",
      "test_visible.py": "from ledger import Ledger\n\n\ndef test_basic():\n    x = Ledger()\n    x.add('cash', 100)\n    assert x.balance('cash') == 100\n"},
     {"test_hidden.py": "from ledger import Ledger\n\n\ndef test_independent_instances():\n    a, b = Ledger(), Ledger()\n    a.add('cash', 100)\n    assert b.balance('cash') == 0 and b.accounts() == []\n\n\ndef test_first_seen_order_and_unknown():\n    x = Ledger()\n    x.add('b', 1)\n    x.add('a', 2)\n    x.add('b', 3)\n    assert x.accounts() == ['b', 'a'] and x.balance('b') == 4 and x.balance('zzz') == 0\n\n\ndef test_explicit_entries_are_copied():\n    seed = [('cash', 5)]\n    x = Ledger(seed)\n    x.add('cash', 5)\n    assert seed == [('cash', 5)] and x.balance('cash') == 10\n"},
     {"ledger.py": "class Ledger:\n    def __init__(self, entries=None):\n        self.entries = list(entries) if entries is not None else []\n\n    def add(self, account, paise):\n        self.entries.append((account, paise))\n\n    def balance(self, account):\n        return sum(p for a, p in self.entries if a == account)\n\n    def accounts(self):\n        seen = []\n        for a, _ in self.entries:\n            if a not in seen:\n                seen.append(a)\n        return seen\n"})
